extracts = ""
i = 0
for d in context:
    i = i + 1
    res = llm_query("You will be given one document. Extract concise, relevant facts that could help solve the following puzzle. Use short bullet points, include direct short quotes when available, and clearly label entities and dates. If nothing relevant, return an empty string.\n\nPuzzle criteria:\n- We seek an individual who founded a museum established between 1972 and 1975 (inclusive). As of Dec 31, 2023, the museum is on the second floor of a building.\n- The museum is 24–25 miles (aerial distance) from a library that opened between 1992 and 1995 and is over 70,000 square feet.\n- The individual was editor and publisher of a magazine for over 30 years.\n- Three marine species have been named in their honor.\n- Their parent had the first name Frank and a sibling had the first name Steve.\n- They died on January 8 between 2021 and 2023 (inclusive) in a different country than their birthplace.\n- In 2014, they received an award in recognition of their work.\n\nFor any relevant item you find in the document, give:\n- Entity type (museum/library/person/family/award/species/magazine/death/location/distance/other)\n- The key detail(s)\n- A brief quote from the document\n\nDocument begins:\n" + d + "\nDocument ends.")
    extracts = extracts + "\n---- Document " + str(i) + " Extracts ----\n" + res

final_prompt = "You will be given aggregated extracts from multiple documents. Identify the ONE individual who satisfies ALL of the following constraints:\n- Founded a museum established between 1972 and 1975 (inclusive).\n- As of Dec 31, 2023, the museum is located on the second floor of a building.\n- The museum is located 24–25 miles (in aerial distance) from a library that opened between 1992 and 1995 and is over 70,000 square feet.\n- The individual was the editor and publisher of a magazine for over thirty years.\n- Three marine species have been named in their honor.\n- This individual had a parent with the first name Frank and a sibling with the first name Steve.\n- They passed away on January 8 between 2021 and 2023 (inclusive) in a country different from their birthplace.\n- In 2014, they received an award in recognition of their work.\n\nInstructions:\n1) Carefully cross-link the facts from the extracts to ensure they refer to the same person and institutions.\n2) If the distance is not explicitly stated, infer plausibility using the locations mentioned (you may approximate aerial distance based on well-known geography within the extracts if both places are named).\n3) Only provide the person’s full name in your final output, with no additional text.\n\nAggregated extracts:\n" + extracts + "\n\nFinal answer (full name only):"

answer = llm_query(final_prompt)
return_result(answer)